  let folded = lean * ((1.0 - abs(side_of)) * w * (fract(h.z * 3.9) - 0.5) * 0.9 * tufted * (1.0 + 0.6 * t));
  let bent = across * (side_of * w * 0.5) + lean * (t * height * sin(mid)) + vec3f(0.0, t * height * cos(mid), 0.0)
    + folded;
